/*
 * Premium composition layer
 *
 * This file intentionally loads after theme-layouts.css. It changes only CSS
 * placement and presentation: React ownership, component identity, game state,
 * portrait canvases, audio and Convai sessions never participate in a theme
 * change. Original Classic is excluded from every rule in this file.
 *
 * Desktop compositions use the existing semantic regions:
 *   h = heading, n = mode navigation, c = coach picker,
 *   d = difficulty, s = coach summary/control, a = launch action.
 *   coach / board / side = the three live-game regions.
 */

/* --------------------------------------------------------------------------
   Shared premium foundation
   -------------------------------------------------------------------------- */

/* Classic keeps its original visual language. On phones, only reserve the
   physical rail lane and keep the launch action in the document flow so fixed
   chrome never covers the setup controls. */
@media (max-width: 760px) {
  html[data-theme="classic"] .app-menu {
    padding-left: max(5.25rem, calc(env(safe-area-inset-left) + 5.25rem));
  }

  html[data-theme="classic"] .menu-workspace {
    width: 100%;
    min-width: 0;
  }

  html[data-theme="classic"] .mode-launch {
    position: static !important;
    inset: auto !important;
    width: 100%;
    padding-bottom: max(1rem, env(safe-area-inset-bottom));
    transform: none !important;
  }

  html[data-theme="classic"] .mode-launch .menu-play {
    position: static !important;
    inset: auto !important;
    width: 100%;
    transform: none !important;
  }
}

@media (min-width: 1280px) and (min-height: 700px) {
  html[data-premium-layout="true"] .menu-workspace {
    width: min(var(--premium-menu-width, 1280px), calc(100vw - 10.5rem));
    display: grid;
    grid-template-columns: repeat(12, minmax(0, 1fr));
    grid-template-rows: var(--premium-menu-rows, auto auto auto auto auto);
    grid-template-areas: var(--premium-menu-areas,
      "h h h h n n n n n n n n"
      "h h h h n n n n n n n n"
      "c c c c c d d d s s s s"
      "c c c c c d d d s s s s"
      ". . . a a a a a a . . .");
    gap: var(--premium-gap, clamp(.72rem, 1.2vw, 1rem));
    align-content: center;
    align-items: stretch;
    overflow: visible;
  }

  html[data-premium-layout="true"] .menu-heading { grid-area: h; }
  html[data-premium-layout="true"] .mode-grid { grid-area: n; }
  html[data-premium-layout="true"] .mode-launch { grid-area: a; }

  /* Unframe the old setup wrapper so its three meaningful sections can join
     the screen-level grid. This is the key IA change: themes no longer merely
     shuffle one large setup rectangle. */
  html[data-premium-layout="true"] .setup-panel {
    display: contents;
  }

  html[data-premium-layout="true"] .setup-panel > .setup-panel-coach {
    grid-area: c;
  }

  html[data-premium-layout="true"] .setup-panel > :nth-child(2) {
    grid-area: d;
  }

  html[data-premium-layout="true"] .setup-panel > .coach-summary-stack {
    grid-area: s;
  }

  html[data-premium-layout="true"] :where(
    .menu-heading,
    .mode-grid,
    .setup-panel > .setup-panel-coach,
    .setup-panel > :nth-child(2),
    .setup-panel > .coach-summary-stack,
    .mode-launch
  ) {
    min-width: 0;
    min-height: 0;
  }

  /* Four modes are always a balanced 2 x 2. Development's fifth Dataset mode
     becomes a full-width lead followed by a balanced 2 x 2: never 3 + 1. */
  html[data-premium-layout="true"] .mode-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-auto-rows: minmax(76px, 1fr);
    gap: var(--premium-mode-gap, .65rem);
    overflow: visible;
  }

  html[data-premium-layout="true"] .mode-grid > .mode-tile {
    grid-column: auto;
    grid-row: auto;
    min-height: 0;
  }

  html[data-premium-layout="true"] .mode-grid:has(> .mode-tile:nth-child(5)) > .mode-tile:first-child {
    grid-column: 1 / -1;
  }

  html[data-premium-layout="true"] :where(
    .setup-panel > .setup-panel-coach,
    .setup-panel > :nth-child(2),
    .setup-panel > .coach-summary-stack
  ) {
    padding: var(--premium-region-pad, clamp(.75rem, 1.25vw, 1rem));
    border: var(--theme-line, 1px) solid var(--theme-border);
    border-radius: var(--premium-region-radius, var(--theme-radius));
    background: var(--premium-region-bg, var(--theme-surface));
    box-shadow: var(--premium-region-shadow, var(--theme-shadow-small));
    overflow: hidden;
  }

  html[data-premium-layout="true"] .coach-summary {
    padding-left: 0;
    border-left: 0;
  }

  html[data-premium-layout="true"] .mode-launch {
    display: flex;
    padding: 0;
  }

  html[data-premium-layout="true"] .mode-launch .menu-play {
    align-self: stretch;
    width: 100%;
    min-height: 52px;
  }

  html[data-premium-layout="true"] .app-shell:not(.analysis-shell) {
    width: min(var(--premium-game-width, 1240px), calc(100vw - 10.5rem));
    max-width: calc(100vw - 10.5rem);
    display: grid;
    grid-template-columns: var(--premium-game-cols, minmax(250px, 280px) minmax(0, 640px) minmax(250px, 280px));
    grid-template-rows: var(--premium-game-rows, minmax(0, 1fr));
    grid-template-areas: var(--premium-game-areas, "coach board side");
    gap: var(--premium-game-gap, 1rem);
    align-content: center;
    align-items: var(--premium-game-align, center);
    overflow: visible;
  }

  html[data-premium-layout="true"] .app-shell:not(.analysis-shell) > .coach-card {
    grid-area: coach;
    align-self: stretch;
    justify-self: stretch;
    width: 100%;
    max-width: none;
    transform: none !important;
  }

  html[data-premium-layout="true"] .app-shell:not(.analysis-shell) > .game-stage {
    grid-area: board;
    align-self: center;
    justify-self: center;
    transform: none !important;
  }

  html[data-premium-layout="true"] .app-shell:not(.analysis-shell) > .side-panel {
    grid-area: side;
    align-self: stretch;
    justify-self: stretch;
    width: 100%;
    max-width: none;
    transform: none !important;
  }

  /* Secondary screens share the theme's directional rhythm while keeping their
     existing controls and DOM. Individual presets override these tracks. */
  html[data-premium-layout="true"] :where(.training-layout, .games-layout, .creator-layout) {
    width: min(var(--premium-secondary-width, 1240px), calc(100vw - 10.5rem));
    max-width: calc(100vw - 10.5rem);
    gap: var(--premium-secondary-gap, 1rem);
  }
}

/* --------------------------------------------------------------------------
   10 / Wooden — tournament cabinet

