  html[data-premium-layout="true"][data-theme="flat-icon"] .mode-grid { grid-area: n !important; }
  html[data-premium-layout="true"][data-theme="flat-icon"] .mode-launch { grid-area: a !important; }
  html[data-premium-layout="true"][data-theme="flat-icon"] .setup-panel > .setup-panel-coach { grid-area: c !important; }
