    height: calc(var(--viewport-h) - var(--topbar-h)) !important;
    min-height: 0 !important;
    grid-template-columns: var(--premium-game-cols) !important;
    grid-template-rows: var(--premium-game-rows) !important;
    grid-template-areas: var(--premium-game-areas) !important;
    gap: var(--premium-game-gap) !important;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .app-shell:not(.analysis-shell) > .coach-card { grid-area: coach !important; }
