  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-field--backstory { grid-area: backstory; }
  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-field--speaking-style { grid-area: speaking; }
  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-field--sample-dialogue { grid-area: dialogue; }
  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-row--voice { grid-area: voice; }
  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-row--model { grid-area: model; }
  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-actions { grid-area: actions; }
  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-actions ~ .hint-text { grid-area: status; }
  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-form > .created-id { grid-area: created; }

  html[data-premium-layout="true"][data-theme="flat-icon"] :where(
    .creator-field--name,
    .creator-section--appearance,
    .creator-field--backstory,
    .creator-field--speaking-style,
    .creator-field--sample-dialogue,
    .creator-row--voice,
    .creator-row--model
  ) {
    min-width: 0;
    padding: .62rem .7rem;
    border: 1px solid var(--theme-border);
    border-radius: 16px 7px 16px 7px;
    background: color-mix(in srgb, var(--theme-surface-2), #fff 24%);
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-section--appearance {
    border-bottom: 7px solid #4ecdc4;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] :where(.creator-field--backstory, .creator-field--sample-dialogue) {
    border-bottom: 7px solid #ffd93d;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-field--speaking-style {
    border-bottom: 7px solid #ff6b6b;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] :where(.creator-row--voice, .creator-row--model, .creator-field--name) {
    border-bottom: 7px solid #6c5ce7;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-model-picker {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: .42rem;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-model-picker button {
    min-height: 58px;
    padding: .4rem .5rem;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-model-picker .coach-picker-avatar-wrap {
    width: 40px;
    height: 40px;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-form textarea {
    min-height: 86px;
    max-height: 112px;
    padding: .58rem .65rem;
    line-height: 1.35;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-form .creator-tall-field {
    min-height: 104px;
    max-height: 118px;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-form :where(input, select) {
    min-height: 44px;
    padding-block: .55rem;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-actions {
    height: 100%;
    align-items: stretch;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .creator-actions .primary-action {
    width: 100%;
    min-width: 0;
    min-height: 58px;
    margin: 0;
    border-radius: 12px 28px 12px 28px;
  }
}

/* The creator route is independently scrollable if dynamic status text,
   browser zoom or translated labels make the maker table taller than a short
   viewport. This explicitly defeats the legacy fixed-height clipping seam. */
html[data-premium-layout="true"][data-theme="flat-icon"] .game-screen[data-screen="creator"] {
  height: var(--viewport-h);
  min-height: var(--viewport-h);
  max-height: var(--viewport-h);
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior-y: contain;
}

html[data-premium-layout="true"][data-theme="flat-icon"] .game-screen[data-screen="creator"] .creator-layout {
  height: auto;
  max-height: none;
  overflow: visible;
}

html[data-premium-layout="true"][data-theme="flat-icon"] .game-screen[data-screen="creator"] .creator-form {
  height: auto;
  max-height: none;
  overflow: visible;
}

@media (max-width: 767px) {
  html[data-premium-layout="true"][data-theme="flat-icon"] .app-menu {
    align-items: start;
    overflow-y: auto;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .menu-workspace {
    display: flex !important;
    flex-direction: column !important;
    height: auto !important;
    min-height: max-content;
    margin-block: 0 !important;
    align-content: flex-start !important;
    overflow: visible !important;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .menu-heading {
    flex: 0 0 auto;
    max-height: none !important;
    overflow: visible !important;
    padding: 1rem 1rem 1.1rem;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .menu-heading h1 {
    max-width: 100%;
    margin-bottom: .45rem;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .menu-heading > p:not(.eyebrow) {
    display: block !important;
    margin-bottom: .7rem;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .menu-api-key-trigger {
    position: static !important;
    display: inline-flex;
    margin-top: .1rem;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .mode-grid {
    flex: 0 0 auto;
    overflow: visible !important;
    padding-right: 0;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .setup-panel {
    flex: 0 0 auto;
    display: grid;
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .mode-launch {
    flex: 0 0 auto;
    padding-block: .25rem 1rem;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .game-screen[data-screen="creator"] .creator-layout {
    display: block;
    width: 100%;
    min-height: calc(var(--viewport-h) - var(--topbar-h));
    margin: 0;
    padding: .75rem .7rem 1.5rem;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .game-screen[data-screen="creator"] .creator-form {
    display: grid;
    grid-template-columns: 1fr;
    gap: .75rem;
    padding: .9rem;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .game-screen[data-screen="creator"] .creator-model-picker,
  html[data-premium-layout="true"][data-theme="flat-icon"] .game-screen[data-screen="creator"] :where(.creator-row--voice, .creator-row--model) {
    grid-template-columns: 1fr;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] .game-screen[data-screen="creator"] .creator-actions .primary-action {
    width: 100%;
    min-height: 48px;
  }

  html[data-premium-layout="true"][data-theme="flat-icon"] :where(
    .mode-tile,
    .coach-picker button,
    .difficulty-picker button,
    .coaching-control-option,
    .menu-play,
    .api-key-badge,
    .menu-auth-slot .auth-control,
    .menu-auth-slot .auth-signin-trigger,
    .menu-auth-slot .auth-avatar-button
  ) {
    min-height: 44px;
  }
}
